<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import {useModelsStore} from './store'
import {errorText,modelApi,type TemplateUsage} from './api'
const props=defineProps<{templateId:string;revisionId:string}>(),emit=defineEmits<{close:[]}>(),models=useModelsStore()
const report=ref<TemplateUsage>(),error=ref(''),busy=ref(false),query=ref(''),matchedOnly=ref(false);let sequence=0
async function load(){const request=++sequence;busy.value=true;error.value='';report.value=undefined;try{const expected=models.snapshot?.libraryDigest;if(!expected)throw {message:'请先读取本机模版库'};const result=await modelApi.templateUsage(props.templateId,props.revisionId,expected);if(request===sequence&&props.templateId===result.templateId&&props.revisionId===result.revisionId){if(expected!==models.snapshot?.libraryDigest)throw {message:'模版库已变化，请重新查询'};report.value=result}}catch(cause){if(request===sequence)error.value=errorText(cause)}finally{if(request===sequence)busy.value=false}}
watch(()=>[props.templateId,props.revisionId],()=>{query.value='';void load()},{immediate:true});onBeforeUnmount(()=>{sequence++})
const rows=computed(()=>report.value?.models.filter(row=>(!matchedOnly.value||row.matched)&&(row.channelLabel+' '+row.modelId+' '+row.state).toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))??[])
const stale=computed(()=>!!report.value&&(report.value.libraryDigest!==models.snapshot?.libraryDigest||report.value.policyDigest!==models.snapshot?.policyDigest||report.value.workspaceDigest!==models.snapshot?.workspaceDigest))
</script>
<template><UiDialog :open="true" title="匹配与使用" wide :busy="busy" @close="emit('close')"><p class="model-muted">所选保存版本：{{ revisionId }}。规则命中与实际采用分别显示；已提交策略也不代表客户端已生效。</p><p v-if="error" role="alert" class="model-error">{{ error }}</p><p v-if="busy" role="status">正在读取精确版本的匹配与引用…</p><p v-if="stale" role="status">本机配置已变化，以下为上次查询结果，请重新读取。</p><template v-if="report"><h3>实际引用</h3><ul><li v-for="(item,index) in report.references" :key="index">{{ item.state }} · {{ item.location }}</li><li v-if="report.historicalDependency">成功保存 / 恢复记录依赖此版本</li></ul><p v-if="!report.references.length&&!report.historicalDependency">没有策略引用或成功保存依赖；规则命中不会自动采用。</p><h3>已知型号匹配</h3><div class="model-inline"><input v-model="query" class="input" type="search" aria-label="搜索匹配与使用" placeholder="搜索渠道或原始ID" /><label><input v-model="matchedOnly" type="checkbox" />仅规则命中</label><span>{{ rows.length }} / {{ report.models.length }} 项</span></div><div class="model-table-scroll"><table class="model-table"><thead><tr><th>范围 / 型号</th><th>所选版本规则</th><th>实际采用此版本</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td>{{ row.state }} · {{ row.channelLabel }}<code class="usage-id">{{ row.modelId }}</code></td><td>{{ row.reason }}</td><td>{{ row.resolutionError?'无法确定：'+row.resolutionError:row.adopted?'是':'否' }}</td></tr></tbody></table></div><p v-if="!report.models.length">暂无已知渠道型号；此结果不证明规则不会匹配其他型号。</p></template><template #actions><UiButton :loading="busy" @click="load">重新读取</UiButton><UiButton @click="emit('close')">关闭</UiButton></template></UiDialog></template>
<style scoped>.usage-id{display:block;overflow-wrap:anywhere;white-space:normal}h3{font-size:var(--text-subtitle)}label{display:flex;gap:var(--space-2);align-items:center}</style>
